<script>
export default {
  name: "CancelledLeaveNotification",

  data() {
    return {
      overlay: false,
      snackbar: false,
      snackbarMessage: "",
      snackbarColor: "success",

      leaveData: {
        practitionerName: "",
        practitionerPosition: "",
        practitionerId: "",
        department: "",
        leaveCategory: "",
        leavePeriod: "",
        startDate: "",
        endDate: "",
        returnDate: "",
        cancelDate: "",
        cancelReason: "",
        requestDate: "",
        originalDays: 0,
        daysUtilized: 0,
        daysCancelled: 0,
        actingSupervisor: "",
        comments: "",
        supportingDocuments: [],
        status: "",
        statusDisplay: "",
      },
    };
  },

  computed: {
    queries() {
      return this.$route.query || {};
    },

    utilizationPercentage() {
      if (this.leaveData.originalDays === 0) return 0;
      return (this.leaveData.daysUtilized / this.leaveData.originalDays) * 100;
    },
  },

  async mounted() {
    let user = this.$store.state.user?.obj?.resource?.id;
    let task = await fetch(
      `/fhir/Basic?user=${user}&usertaskstatus=pending&usertaskcategory=cancelleave&usertaskid=${this.queries.leave}`,
    );
    let response = await task.json();
    if (response && response.entry && response.entry.length) {
      let taskDescr = response.entry[0].resource.extension.find((ext) => {
        return (
          ext.url ===
          "http://ihris.org/fhir/StructureDefinition/user-task-description"
        );
      });
      let statusIndex = taskDescr.extension.findIndex((ext) => {
        return ext.url === "status";
      });
      taskDescr.extension[statusIndex].valueCoding.code = "done";
      taskDescr.extension[statusIndex].valueCoding.display = "Done";

      fetch("/fhir/Basic/" + response.entry[0].resource.id, {
        method: "PUT",
        headers: {
          "Content-Type": "application/fhir+json",
          Accept: "application/fhir+json",
        },
        body: JSON.stringify(response.entry[0].resource),
      });
    }
    await this.loadLeaveData();
  },

  methods: {
    async loadLeaveData() {
      this.overlay = true;
      try {
        const leaveId = this.queries.leave;

        if (!leaveId) {
          throw new Error("Leave request ID is required");
        }

        // Fetch leave request
        const response = await fetch(`/fhir/Basic/${leaveId}`);

        if (!response.ok) {
          throw new Error("Failed to load leave request");
        }

        const leaveRequest = await response.json();

        // Extract practitioner name and details
        const practitionerExt = leaveRequest.extension?.find((ext) =>
          ext.url.includes("practitioner"),
        );
        const practitionerRef = practitionerExt?.valueReference?.reference;

        if (practitionerRef) {
          const practitionerId = practitionerRef.split("/")[1];
          this.leaveData.practitionerId = practitionerId;

          try {
            const practitionerResponse = await fetch(
              `/fhir/Practitioner/${practitionerId}`,
            );
            const practitioner = await practitionerResponse.json();
            const name = practitioner.name?.[0];
            this.leaveData.practitionerName = name
              ? `${name.given?.join(" ")} ${name.family}`.trim()
              : "Unknown";
          } catch (err) {
            console.error("Error loading practitioner:", err);
          }
        }

        // Extract leave category
        this.leaveData.leaveCategory = leaveRequest.extension
          ?.find((ext) =>
            ext.url.includes(
              "http://ihris.org/fhir/StructureDefinition/leave-category",
            ),
          )
          ?.valueReference?.reference?.split("/")[1];

        // Extract leave period
        const leavePeriodExt = leaveRequest.extension?.find((ext) =>
          ext.url.includes("leave-period"),
        );
        this.leaveData.leavePeriod = leavePeriodExt?.valueString || "N/A";

        // Extract dates
        const startDateExt = leaveRequest.extension?.find((ext) =>
          ext.url.includes("start-date"),
        );
        this.leaveData.startDate = startDateExt?.valueDate;

        const endDateExt = leaveRequest.extension?.find((ext) =>
          ext.url.includes("end-date"),
        );
        this.leaveData.endDate = endDateExt?.valueDate;

        const returnDateExt = leaveRequest.extension?.find((ext) =>
          ext.url.includes("return-date"),
        );
        this.leaveData.returnDate = returnDateExt?.valueDate;

        const cancelDateExt = leaveRequest.extension?.find((ext) =>
          ext.url.includes("cancel-date"),
        );
        this.leaveData.cancelDate = cancelDateExt?.valueDate;

        const requestDateExt = leaveRequest.extension?.find((ext) =>
          ext.url.includes("request-date"),
        );
        this.leaveData.requestDate = requestDateExt?.valueDate;

        // Extract cancel reason
        const cancelReasonExt = leaveRequest.extension?.find((ext) =>
          ext.url.includes("cancel-reason"),
        );
        this.leaveData.cancelReason = cancelReasonExt?.valueString;

        // Extract days
        const daysExt = leaveRequest.extension?.find(
          (ext) =>
            ext.url.includes("days") && !ext.url.includes("to-be-cancelled"),
        );
        this.leaveData.daysUtilized = daysExt?.valueInteger || 0;

        // Calculate original days and days cancelled
        if (
          this.leaveData.startDate &&
          this.leaveData.endDate &&
          this.leaveData.cancelDate
        ) {
          const startMoment = this.$moment(this.leaveData.startDate);
          const endMoment = this.$moment(this.leaveData.endDate);
          const cancelMoment = this.$moment(this.leaveData.cancelDate);

          this.leaveData.originalDays = endMoment.diff(startMoment, "days") + 1;
          this.leaveData.daysCancelled = endMoment.diff(cancelMoment, "days");
        }

        // Extract acting supervisor
        const actingSupervisorExt = leaveRequest.extension?.find((ext) =>
          ext.url.includes("acting-supervisor"),
        );
        if (actingSupervisorExt?.valueReference?.reference) {
          const actingId = actingSupervisorExt.valueReference.reference.split(
            "/",
          )[1];
          try {
            const actingResponse = await fetch(
              `/fhir/Practitioner/${actingId}`,
            );
            const actingPractitioner = await actingResponse.json();
            const name = actingPractitioner.name?.[0];
            this.leaveData.actingSupervisor = name
              ? `${name.given?.join(" ")} ${name.family}`.trim()
              : "Unknown";
          } catch (err) {
            console.error("Error loading acting supervisor:", err);
          }
        }

        // Extract comments
        const commentsExt = leaveRequest.extension?.find((ext) =>
          ext.url.includes("comments"),
        );
        this.leaveData.comments = commentsExt?.valueString;

        // Extract supporting documents
        const supportingDocsExts = leaveRequest.extension?.filter((ext) =>
          ext.url.includes("supporting-document"),
        );
        if (supportingDocsExts && supportingDocsExts.length > 0) {
          this.leaveData.supportingDocuments = supportingDocsExts.map(
            (ext) => ext.valueAttachment,
          );
        }

        // Extract status
        const statusExt = leaveRequest.extension?.find(
          (ext) =>
            ext.url.includes("status") || ext.url.includes("request-status"),
        );
        this.leaveData.status = statusExt?.valueCoding?.code;
        this.leaveData.statusDisplay =
          statusExt?.valueCoding?.display || this.leaveData.status;
      } catch (error) {
        console.error("Error loading leave data:", error);
        this.showSnackbar(
          "Error loading cancelled leave notification",
          "error",
        );
      } finally {
        this.overlay = false;
      }
    },

    formatDate(dateString) {
      if (!dateString) return "N/A";
      return this.$moment(dateString).format("DD-MMM-YYYY");
    },

    getStatusColor(status) {
      const colors = {
        cancelled: "orange",
        approved: "green",
        pending: "blue",
        rejected: "red",
      };
      return colors[status] || "grey";
    },

    downloadDocument(doc) {
      // TODO: Implement document download
      console.log("Download document:", doc);
      this.showSnackbar(
        "Document download functionality to be implemented",
        "info",
      );
    },

    showSnackbar(message, color) {
      this.snackbarMessage = message;
      this.snackbarColor = color;
      this.snackbar = true;
    },

    goBack() {
      this.$router.go(-1);
    },
  },
};
